def solve(rows):
    state = 4
    kept_rows = []
    today = 13

    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str):
            match = re.match(r'\|(-?\d+)\|', row)
            if match:
                weight = int(match.group(1))
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        keep = (state + weight + i) % 7 != 3 or i == len(rows) - 1
        if keep:
            kept_rows.append(row)

        if weight == 0:
            state = 4
        else:
            state = (5 * state + weight) % 7

    if not kept_rows:
        return [0, None]

    final_state = state
    kept_length = len(kept_rows)
    rotation = final_state % kept_length
    rotated_rows = kept_rows[rotation:] + kept_rows[:rotation]

    total_quantity = 0
    earliest_expiry = None

    for row in rotated_rows:
        if isinstance(row, list) and len(row) == 2:
            expiry, quantity = row
            if expiry > today:
                total_quantity += quantity
                if earliest_expiry is None or expiry < earliest_expiry:
                    earliest_expiry = expiry

    return [total_quantity, earliest_expiry]

